      await test.step('Open /', async () => {
        await page.goto('/');
      });

      await test.step("Click 'Add Dot Notebook to cart' once", async () => {
        await addButton(page, 'Dot Notebook').click();
      });

      await test.step("Read the accessible name of the cart badge / 'Checkout' link", async () => {
        await expect(cartBadge(page)).toHaveText('1');
        await expect(cartLink(page)).toHaveAccessibleName('Checkout 1 item in cart');
        await expect(cartBadge(page)).toHaveAttribute('aria-label', '1 item in cart');
      });
