        const h1Box = await boxOf(page.getByRole('heading', { level: 1, name: 'Everyday goods, made well', exact: true }));
        expectNear(h1Box.height, 96, 2, 'h1 height (2 lines)');
        expectNear(h1Box.x, 24, 1, 'h1 left gutter');
        expectNear(h1Box.width, 342, 2, 'content width');

